import './paginas/Demandas/Demandas.css'
import { useState, useEffect } from "react";
import axios from 'axios';

function MainDemanda() {
    const [idpaciente, setPaciente] = useState("");
    const [idatividade, setAtividade] = useState("");
    const [idterapeuta, setTerapeuta] = useState("");
    const [demandas, setDemandas] = useState([]);

    useEffect(() => {

        const buscar = async () => {
            const [pacientesRes, vendedoresRes] = await Promise.all([
                axios.get('http://localhost:3001/api/listarprodutos', {
                    // headers: {
                    //     Authorization: `Bearer ${token}`,
                    // },
                }),

                axios.get('http://localhost:3001/api/listarvendedores', {
                    // headers: {
                    //     Authorization: `Bearer ${token}`,
                    // },
                }),
            ]);
        }





        // const getDemandas = async () => {
        //     try {
        //         const response = await axios.get('http://localhost:3001/listarDemanda');

        //         if (response.status === 200) {
        //             setDemandas(response.data)
        //             console.log(response.data);
        //         }
        //         else {
        //             console.log("erro ao carregar as demandas")
        //         }
        //     }
        //     catch (error) {
        //         throw error;
        //     }
        // }

        // getDemandas();
        buscar();
    }, [])


    const handleSubmit = (e) => {
        e.preventDefault();
        console.log(idpaciente);
    };
    return (
        <main className="col-md-12 ms-sm-auto col-lg-12 px-md-4 container-fluid d-flex flex-column align-items-center">

            <div className="container mt-3">
                <h2 className="titulo-principal">
                    Cadastro de demanda
                </h2>
                <div className="caixa-cadastro mx-auto">
                    <form onSubmit={handleSubmit} >

                        <div className="mb-3">
                            <label className="form-label texto-label">Paciente:</label>
                            <select
                                className="form-select campo-input"
                                value={idpaciente}
                                onChange={(e) => setPaciente(e.target.value)}
                            >
                                <option className='CorVermelha' value="">Selecione o paciente</option>
                                {demandas.length === 0 ? (
                                    <option disabled>Sem pacientes</option>
                                ) : (
                                    demandas.map((demanda) => (
                                        <option key={demanda.DemandaID} value={demanda.DemandaID}>
                                            {demanda.Nome}
                                        </option>
                                    ))
                                )}
                            </select>
                        </div>

                        <div className="mb-3">
                            <label className="form-label texto-label">Atividade:</label>
                            <select
                                className="form-select campo-input"
                                value={idatividade}
                                onChange={(e) => setAtividade(e.target.value)}
                            >
                                <option value="">Selecione a atividade</option>
                                {demandas.length === 0 ? (
                                    <option disabled>Sem atividades</option>
                                ) : (
                                    demandas.map((demanda) => (
                                        <option key={demanda.DemandaID} value={demanda.DemandaID}>
                                            {demanda.Atividade}
                                        </option>
                                    ))
                                )}
                            </select>
                        </div>

                        <div className="mb-3">
                            <label className="form-label texto-label">Terapeuta:</label>
                            <select
                                className="form-select campo-input"
                                value={idterapeuta}
                                onChange={(e) => setTerapeuta(e.target.value)}
                            >
                                <option value="">Selecione o terapeuta</option>
                                {demandas.length === 0 ? (
                                    <option disabled>Sem terapeutas</option>
                                ) : (
                                    demandas.map((demanda) => (
                                        <option key={demanda.DemandaID} value={demanda.DemandaID}>
                                            {demanda.Terapeuta}
                                        </option>
                                    ))
                                )}
                            </select>
                        </div>

                        <div className="text-center">
                            <button type="submit" className="botao-cadastrar">
                                Cadastrar
                            </button>
                        </div>
                    </form>
                </div>
            </div>

        </main>
    );
}

export default MainDemanda;
